INSERT INTO market_areas (county, city, zip_code, median_sale_price, avg_price_per_sqft, avg_rent_3br, avg_rent_2br, hud_fmr_3br, avg_days_on_market, months_of_inventory, list_to_sale_ratio, investor_buyer_pct, flood_zone_prevalence, yoy_appreciation_pct, competition_level, ccg_priority, ccg_notes) VALUES
('Pasco', 'Zephyrhills', '33525', 255000, 155, 1750, 1450, 2300, 22, 2.1, 0.97, 35, 'low', 8.5, 'medium', 'primary', 'Strong CCG territory. Concrete block inventory from 1985-1995. Good wholesale and BRRRR market. Derek sends deals here frequently.'),
('Pasco', 'Wesley Chapel', '33544', 390000, 195, 2150, 1800, 2300, 18, 1.8, 0.98, 25, 'low', 11.2, 'high', 'primary', 'High growth area. Newer construction. Good flip market. Competition is higher. Need to move fast.'),
('Pasco', 'Wesley Chapel', '33545', 345000, 175, 2000, 1650, 2300, 20, 1.9, 0.97, 28, 'low', 10.1, 'medium', 'primary', 'Good flip area. Mix of older and newer. Concrete block 90s homes are ideal targets.'),
('Pasco', 'Lutz', '33559', 385000, 192, 2200, 1850, 2300, 16, 1.6, 0.99, 22, 'low', 12.0, 'high', 'secondary', 'Premium Pasco. Higher prices make MAO math harder. Only exceptional deals.'),
('Pasco', 'Land O Lakes', '34637', 375000, 188, 2050, 1700, 2300, 17, 1.7, 0.98, 24, 'low', 11.5, 'medium', 'primary', 'Growing suburb. Good retail buyer demand. Strong flip exit market.'),
('Pasco', 'Land O Lakes', '34638', 365000, 183, 2000, 1650, 2300, 19, 1.8, 0.97, 26, 'low', 10.8, 'medium', 'primary', 'Similar to 34637. Solid market.'),
('Pasco', 'Land O Lakes', '34639', 358000, 179, 1980, 1620, 2300, 21, 2.0, 0.97, 28, 'low', 9.5, 'medium', 'primary', 'Slightly more affordable LOL. Good balance of price/demand.'),
('Pasco', 'New Port Richey', '34652', 238000, 145, 1700, 1400, 2300, 25, 2.5, 0.96, 38, 'medium', 6.5, 'medium', 'primary', 'Older inventory. Lots of concrete block 1975-1990. Strong wholesale and rental play. Flood zones in coastal areas - check carefully.'),
('Pasco', 'New Port Richey', '34653', 218000, 138, 1650, 1350, 2300, 28, 2.8, 0.95, 42, 'medium', 5.8, 'low', 'primary', 'Lower price point. Good wholesale deals. Some flood zone issues near Gulf.'),
('Pasco', 'New Port Richey', '34654', 252000, 151, 1750, 1450, 2300, 24, 2.3, 0.96, 36, 'low', 7.2, 'medium', 'primary', 'East NPR. Better flood zone profile. Good BRRRR territory.'),
('Pasco', 'Trinity', '34655', 378000, 191, 2150, 1800, 2300, 16, 1.5, 0.99, 18, 'low', 12.5, 'high', 'secondary', 'Premium west Pasco. High demand, lower investor presence. Good flip exits but harder entry.'),
('Pasco', 'Hudson', '34667', 222000, 140, 1600, 1300, 2300, 30, 3.0, 0.95, 40, 'high', 4.5, 'low', 'watch', 'More coastal flood zone risk. Older demographic. Slower appreciation. Proceed with caution.'),
('Pasco', 'Port Richey', '34668', 212000, 134, 1550, 1280, 2300, 32, 3.2, 0.94, 42, 'high', 4.0, 'low', 'watch', 'Similar concerns to Hudson. Heavy flood zone. Not primary territory.'),
('Pasco', 'Hudson', '34669', 237000, 146, 1650, 1380, 2300, 27, 2.6, 0.96, 38, 'medium', 6.0, 'low', 'watch', 'Inland Hudson. Better than coastal. Still cautious on flood and demographics.'),
('Pasco', 'San Antonio', '33576', 312000, 159, 1850, 1500, 2300, 23, 2.2, 0.97, 32, 'low', 8.0, 'primary', 'Good rural Pasco. Older concrete block inventory. Less competition. Good BRRRR deals come through here.'),
('Pasco', 'Dade City', '33523', 248000, 148, 1700, 1400, 2300, 26, 2.4, 0.96, 35, 'low', 6.5, 'medium', 'primary', 'Small market but deals exist. Less competition than Wesley Chapel. Worth monitoring.'),
('Pasco', 'Odessa', '33556', 498000, 245, 2500, 2100, 2300, 14, 1.2, 0.99, 15, 'low', 15.0, 'high', 'secondary', 'Premium west Hillsborough/Pasco border. Very high prices. Only exceptional deals at significant discount.'),

