('Hillsborough', 'Valrico', '33596', 355000, 178, 2100, 1750, 2533, 16, 1.5, 0.98, 23, 'low', 10.8, 'medium', 'primary', 'Stronger Valrico. Good retail exit. Somewhat competitive.'),
('Hillsborough', 'Dover', '33527', 298000, 153, 1850, 1520, 2533, 22, 2.0, 0.97, 32, 'low', 8.5, 'medium', 'primary', 'East Hillsborough. Less competitive. Older inventory. Some deals come through here.'),
('Hillsborough', 'Seffner', '33584', 282000, 148, 1800, 1480, 2533, 23, 2.2, 0.96, 34, 'low', 8.0, 'medium', 'primary', 'Underappreciated market. Older concrete block. Good BRRRR opportunity.'),
('Hillsborough', 'Thonotosassa', '33592', 318000, 161, 1900, 1550, 2533, 21, 2.0, 0.97, 30, 'low', 8.8, 'low', 'primary', 'Rural feel but close to Tampa. Less competition. Larger lots common. Good for certain buyer profiles.'),
('Hillsborough', 'Plant City', '33566', 288000, 150, 1820, 1480, 2533, 22, 2.1, 0.97, 32, 'low', 8.0, 'medium', 'secondary', 'East Hillsborough. Growing but different market dynamics. Check before pursuing.'),
('Hillsborough', 'Plant City', '33567', 268000, 143, 1750, 1420, 2533, 24, 2.3, 0.96, 34, 'low', 7.5, 'low', 'secondary', 'Less competitive Plant City. Older inventory. Some deals possible.'),
('Hillsborough', 'Gibsonton', '33534', 282000, 148, 1820, 1500, 2533, 23, 2.2, 0.96, 33, 'medium', 7.2, 'medium', 'watch', 'Some flood zone concerns near Alafia River. Check carefully. Otherwise decent market.'),
('Hillsborough', 'Wimauma', '33598', 272000, 143, 1750, 1420, 2533, 24, 2.3, 0.96, 35, 'low', 7.0, 'low', 'watch', 'Rural south Hillsborough. Growing but slower. Some agricultural area concerns.'),
('Hillsborough', 'Lithia', '33547', 452000, 218, 2400, 2000, 2533, 15, 1.4, 0.99, 18, 'low', 13.5, 'very_high', 'secondary', 'Fishhawk area. Very high demand, premium prices. Very hard to make flip math work. Only exceptional deals.'),

