-- ── REHAB COST BENCHMARKS ────────────────────────────────────
INSERT INTO rehab_costs (trade, item, scope, unit, cost_low, cost_mid, cost_high, florida_specific_notes, common_hidden_costs, typical_overrun_pct, red_flags, inspector_notes) VALUES
-- ROOF
('Roof', 'Asphalt Shingle Replacement', 'full', 'per_home', 9000, 13000, 18000, 'Florida requires enhanced wind resistance. 130 mph rated shingles in most counties. Peel-and-stick underlayment now code in many areas.', 'Rotted decking adds $1,500-4,000. Check for multiple layers - Florida allows only one re-roof before tear-off required.', 15, 'Multiple layers, visible sagging, soft spots, active leaks, improper flashing', 'Always get on the roof or use drone. Age and nail pattern matter for insurance.'),
('Roof', 'Metal Roof Replacement', 'full', 'per_home', 16000, 22000, 35000, 'Metal preferred by insurance companies - can reduce premiums 15-25%. Better long-term. Justifiable on BRRRR holds.', 'Decking replacement commonly needed. Flashing and trim add cost.', 12, 'Previous improper installation, rust spots, loose panels', 'Wind mitigation credits for metal roofs are significant. Worth considering on holds.'),
('Roof', 'Roof Repair/Patch', 'repair', 'per_home', 800, 2500, 6000, 'Minor repairs often band-aids. If roof is 15+ years old, factor full replacement in your numbers even if patch seems feasible.', 'Hidden damage often discovered during repair - escalates to replacement.', 50, 'Age over 15 years, missing shingles, granule loss in gutters', 'If insurance claim involved, must disclose. Check permit history.'),
('Roof', 'Flat/TPO Roof', 'full', 'per_home', 8000, 14000, 22000, 'Common on Florida additions and older homes. TPO is preferred material. EPDM less common.', 'Decking replacement, drainage issues', 20, 'Ponding water, blistering, alligatoring of old tar', 'Critical to get properly pitched - ponding causes premature failure in Florida rain.'),

-- HVAC
('HVAC', 'Full HVAC Replacement (3-ton central)', 'full', 'per_home', 7500, 10000, 14000, 'Florida HVAC lifespan is 12-15 years vs national 15-20 due to continuous heavy use. Budget accordingly.', 'Ductwork replacement adds $3,000-6,000 if needed. Permit required in most Florida counties.', 15, 'Unit over 12 years, R-22 refrigerant (obsolete), rust, frequent repairs', 'Always run unit and check airflow to every room. Note brand - Bryant/Carrier/Lennox preferred.'),
('HVAC', 'HVAC Repair', 'repair', 'per_home', 400, 1500, 4000, 'Common repairs: capacitors $200-400, compressor $1,500-3,000, coil leaks $1,000-2,500', 'Old refrigerant types (R-22) must be replaced entirely - no recharge available.', 40, 'Old unit, repeated repairs, high utility bills', 'If capacitor replaced recently, unit may still have life. Compressor replacement on old unit = replace whole unit.'),
('HVAC', 'Ductwork Replacement', 'full', 'per_home', 3000, 5000, 8000, 'Florida duct systems in attics degrade quickly from heat. Flex duct common in 80s-90s homes.', 'Mold in ducts common in humid climate - adds remediation cost.', 20, 'Torn flex duct visible, mold smell from vents, poor airflow distribution', 'New HVAC with old duct defeats the purpose. Budget both if ducts are 20+ years old.'),
('HVAC', 'Mini-Split System', 'replacement', 'per_home', 4000, 7000, 12000, 'Good for additions, garages, or older homes without central air. Brands: Daikin, Mitsubishi preferred.', 'Electrical upgrade may be needed', 10, 'Window units only (no central system)', 'Mini-splits are viable rental option. Reduces cost vs full central air.'),

-- PLUMBING
('Plumbing', 'Full Re-Pipe (PEX)', 'full', 'per_home', 5000, 8000, 14000, 'PEX is preferred material. Faster install, more flexible, freeze-resistant (though less critical in FL).', 'Patching drywall after re-pipe adds $1,000-3,000. Permit required.', 15, 'Galvanized pipes (pre-1970), polybutylene (gray plastic, 1978-1995), active leaks, low pressure', 'Run all faucets. Check under sinks and at water heater connections. Look for galvanized at water meter connection.'),
('Plumbing', 'Water Heater Replacement', 'replacement', 'each', 900, 1400, 2200, 'Standard tank: $900-1,400. Tankless: $1,800-3,500. Check age - anything 12+ years replace.', 'Gas line issues if converting to gas. Expansion tank often required by code.', 5, 'Rust, leaking, older than 12 years, original to house', 'Note gas vs electric. Gas water heater in FL usually means natural gas or propane is available.'),
('Plumbing', 'Toilet Replacement', 'replacement', 'each', 200, 350, 600, 'Budget $200-350 per toilet installed. Always replace on full gut. Running toilets waste water.', 'Flange condition often hidden', 5, 'Running constantly, cracked tank/bowl, wobbly', 'Check subfloor condition when replacing - water damage common around toilets.'),
('Plumbing', 'Septic System Service', 'repair', 'per_home', 500, 1500, 15000, 'Critical in Hernando, rural Pasco, rural Hillsborough. Pump every 3-5 years. Full replacement is $8,000-15,000+.', 'Drain field failure is catastrophic. County inspection required on sale in some areas.', 50, 'Odor in yard, wet soggy areas over drain field, slow drains throughout house', 'Hernando County has many septic systems. Always ask about septic vs sewer on rural or older properties.'),
('Plumbing', 'Minor Plumbing Repairs', 'repair', 'per_home', 500, 1500, 4000, 'Faucets, drains, supply lines, basic repairs', 'Rotted subfloor from leaks discovered during repair', 25, 'Multiple slow drains, musty smells, water stains on ceilings', 'Budget $1,500 for plumbing repairs on a cosmetic flip as standard contingency.'),

-- ELECTRICAL
('Electrical', 'Panel Upgrade to 200A', 'replacement', 'each', 1800, 2800, 4500, 'Required for most modern updates. Essential for EV charging, modern appliances. Permit always required.', 'Meter base replacement often needed (+$500). POCO coordination for power shutoff.', 15, 'Federal Pacific Stab-Lok (fire hazard), Zinsco/Sylvania, fuses, undersized service, aluminum wiring', 'Check brand: Federal Pacific and Zinsco panels are safety hazards - disclose to buyer.'),
('Electrical', 'Full Rewire', 'full', 'per_home', 8000, 12000, 20000, 'Needed for aluminum wiring homes (1965-1973) or knob-and-tube. Permit required. Major disruption.', 'Drywall repair after pulling wire adds $2,000-5,000', 20, 'Aluminum wiring (silvery color at outlets), knob-and-tube, burnt smells, tripping breakers', 'Aluminum wiring is insurable but most buyers and insurance companies want copper.'),
('Electrical', 'GFCI/Outlet/Switch Updates', 'repair', 'per_home', 500, 1500, 3000, 'Required in kitchens, baths, garage, exterior. Code requirement on any permit work.', 'Sometimes triggers full update requirement', 10, 'Two-prong outlets throughout, ungrounded wiring', 'Budget $500-1,500 for a cosmetic flip to update visible electrical.'),
('Electrical', 'Electrical Repair/Misc', 'repair', 'per_home', 500, 2000, 5000, 'Covers various repairs, circuit additions, light fixture replacement', NULL, 15, 'Frequently tripping breakers, burning smell, hot outlets or switch plates', 'Include $1,000 electrical budget on every flip as standard contingency.'),

-- KITCHEN
('Kitchen', 'Cosmetic Kitchen Update', 'light', 'per_home', 5000, 9000, 14000, 'Paint cabinets, new hardware, new countertops (laminate), new faucet, appliances. Maximum budget on sub-$300K flips.', 'Cabinet boxes must be solid. If boxes are damaged, escalates to medium or full.', 15, 'Cabinet box damage, outdated layout that cannot work with cosmetic update', 'Most effective dollar spend in a flip. Focus on countertops and appliances for maximum impact.'),
('Kitchen', 'Mid-Range Kitchen Remodel', 'medium', 'per_home', 14000, 22000, 32000, 'New cabinets (stock/semi-custom), quartz or granite countertops, new appliances, tile backsplash. Appropriate for $350-500K flips.', 'Cabinet delivery lead times can delay project. Order early.', 20, 'Structural wall issues, plumbing relocation needed', 'Quartz countertops are table stakes for $400K+ flip buyers in Tampa Bay.'),
('Kitchen', 'Full Kitchen Gut/Custom', 'full', 'per_home', 25000, 40000, 65000, 'Custom cabinets, high-end appliances, full layout change. Only for luxury flips $600K+.', 'Layout changes require plumbing/electrical relocation - adds $5,000-15,000', 25, NULL, 'Rarely justified in CCG target markets. Budget accordingly.'),
('Kitchen', 'Appliance Package', 'replacement', 'per_home', 2200, 3500, 6000, 'Stainless: range, dishwasher, microwave (above range or built-in), refrigerator. Samsung, LG, GE preferred for resale. Buy package deals at Lowe''s/Home Depot.', NULL, 5, 'Worn, mismatched, non-stainless appliances will kill buyer first impressions', 'Refrigerator: include for rentals, include on flips if ARV above $350K.'),

-- BATHROOMS
('Bathrooms', 'Cosmetic Bathroom Update', 'light', 'per_bath', 2500, 5000, 8000, 'New vanity, toilet, paint, fixtures, mirror, light bar. Refinish or retile tub surround. Works on most flips.', 'Subfloor damage around toilet/tub is common and hidden', 20, 'Tile damage, wet subfloor, old fiberglass tub delaminating', 'Budget $3,500 per bath cosmetic refresh as standard flip line item.'),
('Bathrooms', 'Full Bathroom Gut', 'full', 'per_bath', 8000, 14000, 22000, 'New everything: shower/tub, tile, vanity, toilet, plumbing fixtures, exhaust fan. For premium flips or when bathroom is truly destroyed.', 'Shower pan replacement, subfloor issues', 25, 'Active leaks, mold, tile completely failed', 'Frame and rough-in: budget additional 2 weeks of timeline.'),

-- FLOORING
('Flooring', 'Luxury Vinyl Plank (LVP)', 'full', 'sqft', 2.80, 3.80, 5.20, 'Most popular choice for Florida flips. Water-resistant, durable, looks great. 6mm+ thick. Use same throughout living areas for clean look.', 'Subfloor leveling adds $0.50-2.00/sqft if needed', 10, 'Concrete slab with moisture issues (common in FL), extreme height variation', 'Shaw or LifeProof (Home Depot) are reliable brands. Order 10% overage.'),
('Flooring', 'Tile (Ceramic/Porcelain)', 'full', 'sqft', 4.50, 7.00, 12.00, 'Great for Florida - durable, cool underfoot, moisture resistant. Common in kitchens, baths, entries. Labor-intensive.', 'Subfloor prep critical. Cracked tile after install = improper prep.', 15, 'Uneven slab, moisture in slab', 'Large format tile (12x24 or bigger) is current buyer preference in $350K+ market.'),
('Flooring', 'Carpet (Bedrooms Only)', 'full', 'sqft', 1.80, 3.00, 5.00, 'Limit carpet to bedrooms only. Buyers increasingly want hard surface throughout but budget limits often require carpet in bedrooms.', NULL, 5, NULL, 'Install LVP or tile throughout if ARV supports it. Carpet in bedrooms only for budget flips.'),
('Flooring', 'Subfloor Repair/Leveling', 'repair', 'sqft', 3.00, 6.00, 12.00, 'Concrete slab cracking, moisture damage, soft spots. Very common in older Florida homes.', 'Hidden extent often worse than initially visible', 40, 'Soft spots when walking, visible sag, areas that feel hollow, water stains on old vinyl', 'Budget $2,000 subfloor contingency on every pre-2000 home.'),

-- PAINT
('Paint', 'Interior Paint (Full House)', 'full', 'per_home', 3000, 5000, 8000, 'Walls, ceilings, trim, doors. Two coats. Price increases with ceiling height and custom trim work.', 'Popcorn ceiling removal adds $1.50-3.00/sqft if needed.', 10, 'Heavy patching needed, lead paint (pre-1978 homes), major staining', 'Popcorn ceilings test for asbestos if pre-1980 (required before disturbing). Budget $2,000-4,000 for removal.'),
('Paint', 'Exterior Paint', 'full', 'per_home', 3500, 6000, 10000, 'Concrete block: paint peels if not properly prepped. Must use elastomeric paint. Stucco painting is specialty work.', 'Wood rot repair on soffits, fascia, window trim discovered during prep', 20, 'Peeling, bubbling, efflorescence (white salt deposits), wood rot at trim', 'In FL, exterior paint every 7-10 years on concrete block. Include pressure wash in scope.'),

-- LANDSCAPING
('Landscaping', 'Basic Cleanup and Refresh', 'light', 'per_home', 800, 2000, 5000, 'Mow, edge, trim, mulch, clean up. Some new plants at entry. Pressure wash driveway and sidewalk.', 'Irrigation system repair adds $500-2,000 if broken', 10, 'Massive tree removal needed, drainage issues, dead landscaping throughout', 'Never underestimate curb appeal. $1,500 on landscaping can make or break an offer price.'),
('Landscaping', 'Full Landscaping Refresh', 'full', 'per_home', 4000, 8000, 15000, 'New sod, plants, mulch, irrigation repair/install, landscape lighting at entry. For premium flips or complete dead landscaping.', 'Tree removal, stump grinding', 15, 'Dead trees too close to house, erosion, zero curb appeal', 'Sod in Florida: Bahia (cheap, low maintenance), St. Augustine (thick, green, more expensive). Use St. Augustine for flips.'),

-- WINDOWS AND DOORS
('Windows/Doors', 'Impact Window Replacement', 'full', 'per_home', 12000, 18000, 30000, 'REQUIRED in coastal counties. Mandatory within 1 mile of coast in most FL counties post-2001. Strong insurance discount.', 'Permit always required. Hurricane straps often inspected at same time.', 15, 'Missing impact windows in areas that require them, broken seals, fogging', 'Major insurance savings - often $1,500-3,000/year reduction. Mention to buyers.'),
('Windows/Doors', 'Standard Vinyl Window Replacement', 'full', 'per_home', 6000, 10000, 16000, 'Non-impact but improved efficiency. Double-pane throughout. Appropriate for inland properties where impact not required.', NULL, 10, 'Broken seals, fogging, single-pane throughout on older home', 'Check if county requires impact or just upgraded windows.'),
('Windows/Doors', 'Front Door Replacement', 'replacement', 'each', 800, 1500, 3000, 'Front door is major first impression. Steel or fiberglass preferred. Insulated. Impact-rated if required.', NULL, 5, 'Old hollow core entry doors, damaged frame', 'Budget $1,200 for solid door with new hardware on any flip.'),
('Windows/Doors', 'Sliding Glass Door Replacement', 'replacement', 'each', 1500, 2800, 5500, 'Very common in Florida homes. Impact or non-impact. Standard size: 6-foot or 8-foot.', 'Frame condition and track damage hidden', 10, 'Difficult to open/close, broken lock, fogged glass', 'Test operation on every inspection. Budget replacement if more than 15 years old.'),

-- PERMITS AND MISC
('Permits/Admin', 'Building Permits and Inspections', 'full', 'per_home', 1500, 3000, 6000, 'Florida permit costs: structural/addition $2,000-8,000, reroofing $200-500, HVAC $150-350, electrical $200-400, plumbing $150-300. Impact fees additional for new construction.', 'Impact fees for additions can be substantial. Check before scope change.', 10, 'Open permits from previous owners - ALWAYS pull permit history before purchasing', 'Check permit status at county building dept for every deal. Unpermitted work = liability.'),
('Misc', 'Contingency Budget', 'full', 'per_home', 3000, 6000, 12000, 'Add 10-15% of hard costs as contingency. Florida homes hide surprises - mold, termites, Chinese drywall, foundation cracks, underground oil tanks.', 'Chinese drywall (2004-2007 construction or imports): corrosive smell, black AC coils, immediate red flag', 0, 'Any home 1960-1975 for lead/asbestos. 2004-2007 imports for Chinese drywall. Any moisture smell.', 'NEVER skip contingency. It is not optional. It is a cost of doing business.'),
('Misc', 'Termite Treatment and Damage', 'repair', 'per_home', 500, 2000, 15000, 'Subterranean and drywood termites common in FL. Treatment: $500-1,500. Damage repair: $2,000-15,000+.', 'Structural damage extent often unknown until opened up', 50, 'Mud tubes on foundation, hollow sound when knocking on wood, termite frass (pellets), wings near windows', 'Get termite inspection (WDO) on every deal. Negotiate repair credit if active infestation.'),
('Misc', 'Mold Remediation', 'repair', 'per_home', 2000, 7000, 25000, 'Florida climate + moisture = mold. Small area ($2K-4K). Larger areas or hidden in walls/attic ($10K-25K+). Disclosure required.', 'Full extent often hidden behind walls. Open and inspect suspicious areas before buying.', 60, 'Musty smell, visible black or green spots, water staining, high humidity readings inside home', 'Mold remediation contractor required. Causes: roof leak, plumbing leak, AC condensate, improper vapor barrier.'),
('Misc', 'Pool Repair and Resurfacing', 'repair', 'per_home', 2000, 8000, 20000, 'Pool adds value in FL but also cost. Resurfacing: $4,000-10,000. Equipment: $2,000-5,000. Safety fence: $2,000-4,000.', 'Structural cracks can be catastrophic - get pool inspection', 30, 'Green water, equipment failure, cracks in shell, missing safety barrier', 'Pool adds approximately $15,000-30,000 to ARV in CCG target markets. Worth maintaining/repairing if in good shape.');

-- ── CCG BUY CRITERIA ─────────────────────────────────────────
INSERT INTO buy_criteria (deal_type, label, min_beds, min_baths, min_sqft, max_sqft, preferred_construction, year_built_min, year_built_max, property_types, min_profit, min_profit_pct, min_roi_pct, max_purchase_price, hml_rate_pct, hml_ltv, hml_points, preferred_counties, acceptable_counties, max_distance_from_tampa_miles, avoid_flood_zones, avoid_hoa, notes) VALUES
('flip', 'CCG Standard Flip', 3, 2, 1100, 3200, ARRAY['concrete_block','frame'], 1975, 2010, ARRAY['sfr'], 30000, 10, 25, 400000, 9.5, 90, 2, ARRAY['Pasco','Hillsborough','Hernando'], ARRAY['Pinellas','Polk'], 60, TRUE, FALSE, 'Core flip business. Buy at MAO (70% ARV minus repairs). Full retail rehab. 4-6 month cycle. Target $35K+ avg profit. Concrete block preferred but frame acceptable. $30K minimum profit absolute floor.'),
('brrrr', 'CCG BRRRR Portfolio Builder', 3, 2, 1100, 2200, ARRAY['concrete_block'], 1978, 1999, ARRAY['sfr'], 0, 0, 0, 300000, 9.5, 90, 2, ARRAY['Pasco','Hernando','Hillsborough'], ARRAY['Pinellas','Polk'], 60, TRUE, FALSE, 'Portfolio building via BRRRR. Concrete block REQUIRED. 1978-1999 builds. Within 1 hour Tampa. Refi at 6.75% DSCR, 75% LTV. Goal: leave <20% cash in deal, positive cash flow after refi. Primary zips: Zephyrhills, Wesley Chapel, Spring Hill, Ruskin, East Hillsborough.'),
('rental', 'CCG Standard Rental', 3, 2, 1100, 2000, ARRAY['concrete_block','frame'], 1978, 2005, ARRAY['sfr'], 0, 0, 0, 280000, 9.5, 90, 2, ARRAY['Pasco','Hernando','Hillsborough'], ARRAY['Pinellas','Polk'], 60, TRUE, FALSE, 'Buy-and-hold rental. DSCR loan at 6.75%, 75% LTV. Minimum positive cash flow after DSCR payment. Property management at 10%. Must work as rental from day 1 - not just hoping for appreciation.'),
('wholesale', 'CCG Wholesale Assignment', 3, 2, 900, 3000, ARRAY['concrete_block','frame'], 1970, 2015, ARRAY['sfr','duplex'], 15000, 0, 0, 350000, 9.5, 90, 2, ARRAY['Pasco','Hillsborough','Hernando','Pinellas'], ARRAY['Polk'], 75, FALSE, FALSE, 'Lock at 60-65% ARV minus repairs maximum. Assignment fee target $15,000-30,000. Speed is everything - must move within 14 days. Have buyer before or at time of lock. Broader criteria than flip since passing to flipper buyer.');

-- Insert BRRRR specific details
UPDATE buy_criteria SET 
  brrrr_refi_rate = 6.75,
