  brrrr_target_cashflow = 200
WHERE deal_type = 'brrrr';

UPDATE buy_criteria SET
  rental_dscr_rate = 6.75,
  rental_dscr_ltv = 75,
  rental_min_cashflow = 0,
  rental_target_cashflow = 150
WHERE deal_type = 'rental';

UPDATE buy_criteria SET
  wholesale_min_assignment_fee = 15000,
  wholesale_max_buy_pct_arv = 65
WHERE deal_type = 'wholesale';

-- ── NEGOTIATION PLAYBOOK ─────────────────────────────────────
INSERT INTO negotiation_playbook (situation, wholesaler_grade, deal_type, context, recommended_approach, example_script, what_not_to_do, follow_up_if_no_response, success_indicators, failure_indicators, escalate_to_caleb_if, notes) VALUES
('opening_offer', 'A', 'any', 'First contact with trusted wholesaler on a new deal', 'Be direct and personal. Show interest but dont reveal max. Use their name. Reference relationship history if applicable. Keep it short - under 3 sentences on text.', 'Hey {name} - saw the {address} deal come through. Looks interesting. What''s your best number? We move fast, all cash.', 'Do not reveal MAO. Do not apologize for offering below ask. Do not send a formal letter for initial text contact.', 'If no response in 4 hours: "Hey {name} still interested in {street}? Can move fast." If no response in 24 hours: follow up 2.', 'Quick response, willing to discuss price, engagement', 'No response after 48 hours, immediate hard no with no conversation', 'Never - handle this autonomously once trust unlocked', 'A-grade wholesalers respond to direct, confident communication. They deal volume and need reliable buyers. Show you are that buyer.'),
('opening_offer', 'B', 'any', 'First contact with moderately reliable wholesaler', 'More business-focused. Reference your criteria clearly. Dont waste time with someone who wont move.', 'Hey {name} - {address} is in our buy box. Can you work with {our_opening_offer}? We can close in 14 days, cash.', 'Do not invest heavy relationship energy on first deal. Earn trust through performance first.', 'If no response in 6 hours: one follow-up. If no movement after 48 hours, soft no and move on.', 'Willing to negotiate, comes down at least somewhat', 'Refuses to budge, immediately jumps to "I have other buyers"', 'If they counter above MAO', 'B-grade wholesalers need to see you''re serious but also that you won''t overpay. Be efficient.'),
('opening_offer', 'unknown', 'any', 'First contact with wholesaler we have no history with', 'Slightly more cautious. Introduce CCG briefly. Be direct on price. Assess their response quality.', 'Hey {name} - we''re active cash buyers in {county} County. Saw {address} - interested. Can you do {our_opening_offer}? We close fast and clean.', 'Do not explain CCG in detail. Do not get lengthy. Watch out for daisy chain signals.', 'One follow-up maximum at 24 hours if no response.', 'Professional response, willing to discuss, knows their deal', 'Vague responses, cant answer basic questions about the deal, pressure without engagement', 'If deal is above $250K purchase price', 'Unknown wholesalers get evaluated on communication quality in the first exchange. Assess credibility.'),
('counter_above_mao', 'any', 'flip', 'Wholesaler countered above our MAO. Deal is over ceiling.', 'Use comps to justify our position. Never say MAO. Frame it as the math not working. Leave door open.', 'I hear you on the price. We ran the comps - last three 3/2s in that zip sold at {avg_comp}. Our rehab budget is {rehab}. At {their_counter}, the math gets really tight for us. Anything closer to {our_offer} and we can make it work?', 'Do not say "that''s our max." Do not get emotional. Do not escalate into ultimatum territory.', 'If they dont move: soft no. "Not there for us at that number. If anything changes, we''d love another shot."', 'They come down at least 5% toward your number', 'They hold firm and reference another buyer immediately (likely true - walk)', 'If counter is within $10K of MAO and the deal is really strong', 'The comp-based objection is your strongest tool. You''re not being cheap - the market doesn''t support the price.'),
('wholesaler_ghosting', 'any', 'any', 'Sent offer, no response for 4+ hours', 'One direct follow-up. Reference time sensitivity. Dont be needy.', 'Hey {name} - still interested in {address} if it''s available. Can we connect today?', 'Do not send multiple texts in sequence. Do not ask why they havent responded. Do not apologize.', 'If no response after follow-up at 24h: "Hey - going to move on from {address} if we cant connect today. Let me know." Then move on.', 'They respond and re-engage', 'Continued silence after second follow-up', 'Never - this is Adam''s call to make. If 48h no response, mark dead.', 'Wholesalers ghost for many reasons - busy, went with other buyer, deal fell apart. Dont over-pursue. Your time has value.'),
('other_buyer_pressure', 'any', 'any', 'Wholesaler claiming they have another buyer interested', 'Acknowledge it, dont panic, stay at your number. If deal is truly good, slightly increase urgency but not price.', '"Understood - we''re at {our_offer} and thats where the math works for us. If the other offer falls through or doesnt close, we''re here." OR if you want to close: "Okay, we can move to {slightly_higher} if you can give me a signed contract today."', 'Do not immediately jump to MAO. Do not assume they''re bluffing. Do not show desperation.', 'If they go with other buyer: "No worries. Keep us in mind - we close every deal we sign." Track outcome for credibility assessment.', 'They accept your counter or reveal the "other buyer" was pressure tactic', 'They go with other buyer (assess: was price the issue or credibility?)', 'If the deal is exceptional and you want to go to 95%+ of MAO', 'The other-buyer tactic is 50% real, 50% pressure. Stay cool. Your reputation for closing matters more long-term.'),
('pof_request', 'any', 'any', 'Wholesaler or seller requesting proof of funds before discussing price', 'Send POF immediately. Never make them wait for this. Having POF ready = professional credibility.', 'Send the CCG/trust POF letter. "Attached is our proof of funds. We''re ready to move as soon as we align on price."', 'Do not question why they need it. Do not make them ask twice.', NULL, 'They receive it and continue negotiation', 'POF shows amount that doesn''t align with deal size', 'Never - send POF automatically on request', 'POF response time under 10 minutes separates professionals from amateurs. Speed here builds credibility.'),
('arv_pushback', 'any', 'any', 'Wholesaler pushes back on our lower ARV estimate', 'Stand by Urban''s analysis. Reference actual comp sales. Be specific with data. Dont capitulate on ARV without real evidence.', '"We ran the comps specifically - the last 3/2 in that zip sold at {comp1} on {date1} and {comp2} on {date2}. Our ARV of {our_arv} is the supportable number based on what buyers are actually paying. We can''t go off optimistic projections."', 'Do not accept their ARV without evidence. Do not just split the difference to be nice.', NULL, 'They accept Urban''s analysis or provide credible comps that change your view', 'They provide recent comparable sales that genuinely support higher ARV (update Urban)', 'If wholesaler provides comps that legitimately move ARV by more than 5%', 'Data wins. If you have better data, you win. If they have better data, update your position. Never fight data with ego.'),
('soft_no', 'any', 'any', 'Deal doesnt work at current price. Walking away but preserving relationship.', 'Be warm, be brief, leave the door open. They should want to call you first next time.', '"Doesnt work for us at that number, {name}. Keep us in mind - we''re buying every month and we close what we sign. If anything else comes through, shoot it our way."', 'Do not explain your reasoning in detail. Do not be cold or abrupt. Do not burn the bridge.', NULL, 'They keep you in mind for future deals', NULL, 'Never - Adam handles all soft nos autonomously', 'Every soft no is a relationship investment. Do it right every time.'),
('daisy_chain_detected', 'any', 'any', 'Signs that wholesaler doesnt actually control the deal - they are assigning from another wholesaler', 'Ask direct questions about contract control. Request to see their purchase agreement. Be cautious about closing timeline.', '"Hey {name} - quick question: are you the original buyer under contract, or are you assigning from another party? Want to make sure we''re clear on the chain before we move forward."', 'Do not proceed with an offer until chain is understood. Do not commit to a price that doesnt account for multiple assignment fees.', NULL, 'They clearly explain the chain and it''s manageable', 'Vague or evasive answers about who controls the deal', 'Always - Caleb should know when a deal is a daisy chain', 'Daisy chains add closing complexity and risk. Understand the chain. CCG can still do the deal but needs to know.');

-- ── MESSAGE TEMPLATES ────────────────────────────────────────
INSERT INTO message_templates (name, type, channel, wholesaler_grade, deal_type, template, variables, tone, char_count_target, notes) VALUES
('A-Grade Opening SMS', 'opening_offer', 'sms', 'A', 'any', 'Hey {{name}} - saw the {{street}} deal come through. Looks interesting. What''s the best you can do on price? We move fast, cash close.', ARRAY['name','street'], 'direct', 120, 'Short, confident, curious. Do not mention price first. Let them anchor.'),
('B-Grade Opening SMS', 'opening_offer', 'sms', 'B', 'any', 'Hey {{name}} - {{street}} is in our buy box. Can you work with {{opening_offer}}? Cash, can close in 14 days.', ARRAY['name','street','opening_offer'], 'direct', 110, 'More direct on price given less-established relationship. Efficiency matters.'),
('Unknown WS Opening SMS', 'opening_offer', 'sms', 'unknown', 'any', 'Hey {{name}} - we''re active cash buyers in {{county}} County, close on average in 12 days. Interested in {{street}}. Can you work with {{opening_offer}}?', ARRAY['name','county','street','opening_offer'], 'professional', 130, 'Brief credentialing for unknown relationship. Still direct.'),
('Follow-Up 1 - 4hr', 'follow_up_1', 'sms', 'any', 'any', 'Hey {{name}} - still interested in {{street}} if it''s available. Can we connect today?', ARRAY['name','street'], 'casual', 70, '4-hour follow-up. Single line. Not needy. Just keeping communication open.'),
('Follow-Up 2 - 24hr', 'follow_up_2', 'sms', 'any', 'any', 'Going to move on from {{street}} if we can''t connect today, {{name}}. Let me know.', ARRAY['name','street'], 'casual', 75, '24-hour follow-up. Slight urgency. Last contact before moving on.'),
('Counter Below MAO', 'counter_offer', 'sms', 'any', 'any', 'Ran our numbers on {{street}}, {{name}}. Best we can do is {{our_counter}}. Comps don''t support higher - last 3/2 in that zip sold at {{comp_avg}}. If that works, we can sign today.', ARRAY['street','name','our_counter','comp_avg'], 'direct', 155, 'Counter with comp justification. Sign-today urgency.'),
('Soft No - Price Too High', 'soft_no', 'sms', 'any', 'any', 'Doesn''t work for us at that number, {{name}}. Keep us in mind - we''re buying every month and close what we sign. Next one, give us a shot.', ARRAY['name'], 'warm', 130, 'Warm exit. Relationship preservation. Future-focused.'),
('Hard Walk - Final', 'hard_no', 'sms', 'any', 'any', 'Going to pass on {{street}}, {{name}}. Price doesn''t work for our model. Appreciate you sending it.', ARRAY['street','name'], 'professional', 90, 'Clean exit when soft no didnt work. Professional, no explanation needed.'),
('POF Send', 'pof_send', 'sms', 'any', 'any', 'Attached is our proof of funds, {{name}}. Ready to move as soon as we align on price.', ARRAY['name'], 'professional', 85, 'Immediate POF send. Always attach the actual POF document.'),
('Other Buyer - Hold Position', 'counter_offer', 'sms', 'any', 'any', 'Understood, {{name}}. We''re at {{our_offer}} and that''s where the math works. If the other offer falls through, we''re here and can close quick.', ARRAY['name','our_offer'], 'calm', 125, 'Hold position under other-buyer pressure. Calm, confident.'),
('Other Buyer - Slight Bump', 'counter_offer', 'sms', 'any', 'any', 'Okay {{name}}, we can come to {{bumped_offer}} but I need a signed contract today. That''s our ceiling.', ARRAY['name','bumped_offer'], 'urgent', 90, 'Slight bump under genuine other-buyer pressure. Time constraint included.'),
('Relationship Check-In - A Grade', 'relationship_check', 'sms', 'A', 'any', 'Hey {{name}} - been a minute. How''s deal flow looking? We''re buying steady and looking for good stuff in {{county}} County.', ARRAY['name','county'], 'warm', 105, 'Periodic A-grade relationship maintenance. Every 3-4 weeks if no active deal.'),
('Under Contract Notification - Grant', 'under_contract_notify', 'sms', 'any', 'any', 'Grant - {{address}} is under contract at {{price}}. Close date {{close_date}}. Can you coordinate with title?', ARRAY['address','price','close_date'], 'professional', 105, 'Internal notification to Grant when deal is locked.'),
('Wholesale Blast - A Buyers', 'wholesale_blast', 'sms', 'any', 'wholesale', 'Hey {{name}} - have a {{beds}}/{{baths}} {{sqft}}sf {{type}} in {{city}} at {{asking}}. ARV ~{{arv}}, needs ~{{rehab}} work. Interested? First come first served.', ARRAY['name','beds','baths','sqft','type','city','asking','arv','rehab'], 'direct', 155, 'Wholesale deal blast to buyers list. Send to top-matched buyers first.'),
('Buyer Follow-Up', 'buyer_follow_up', 'sms', 'any', 'wholesale', 'Hey {{name}} - following up on {{address}}. Still available if you want to move. Close date is {{close_date}}.', ARRAY['name','address','close_date'], 'casual', 100, 'Follow-up to buyer who showed interest but havent committed.'),
('Daisy Chain Question', 'opening_offer', 'sms', 'unknown', 'any', 'Quick question {{name}} - are you the buyer under contract on {{address}}, or assigning from another party? Want to understand the chain before we move forward.', ARRAY['name','address'], 'professional', 135, 'Direct daisy-chain inquiry. Ask early before investing time.'),
('Dead Deal - Resurrect', 'opening_offer', 'sms', 'any', 'any', 'Hey {{name}} - saw {{address}} is back available. We looked at it {{days}} days ago but price wasn''t there. Still interested if you can get to {{our_offer}}.', ARRAY['name','address','days','our_offer'], 'casual', 135, 'Dead deal resurrection. Reference history. Show consistency.'),
('Deal Accepted Confirmation', 'under_contract_notify', 'sms', 'any', 'any', 'Perfect, {{name}}. Sending the assignment agreement over now. EMD of {{emd}} will wire by {{emd_date}}. Close date of {{close_date}} works for us.', ARRAY['name','emd','emd_date','close_date'], 'professional', 145, 'Confirmation when deal is accepted. Move immediately to paperwork.'),
('Repair Credit Request', 'counter_offer', 'sms', 'any', 'any', '{{name}} - inspector flagged {{issue}}. Need a {{credit}} credit or price reduction to make the numbers work. What can you do?', ARRAY['name','issue','credit'], 'direct', 110, 'Inspection issue repair credit request. Be specific about the issue and amount needed.'),
('EMD Extension Request', 'follow_up_1', 'sms', 'any', 'any', 'Hey {{name}} - need a quick extension on the EMD deadline to {{new_date}}. Title is working through something on our end. Should be clean.', ARRAY['name','new_date'], 'professional', 115, 'EMD extension if needed. Be honest about reason. Most reasonable wholesalers will grant.'),
('New Wholesaler Introduction', 'opening_offer', 'email', 'unknown', 'any', 'Hey {{name}},\n\nHeard good things about the deals you''re finding in {{county}} County. We''re Coralstone Capital Group - active cash buyers doing 3-4 deals a month in {{counties}} Counties. We close on time, every time, and never retrade.\n\nIf you''ve got anything in the pipeline that fits a 3/2+ concrete block profile, shoot it our way. Happy to look same day.\n\nCaleb Blair\nCoralstone Capital Group\n{{phone}}', ARRAY['name','county','counties','phone'], 'professional', 400, 'Cold outreach to new wholesalers. Email format. Professional introduction.'),
('Weekly Pipeline Summary', 'reporting', 'sms', 'any', 'any', '{{name}} - quick pipeline update: {{under_contract}} under contract, {{offers_out}} offers out, {{hot_pending}} HOT deals pending your review. Top priority: {{top_deal}}.', ARRAY['name','under_contract','offers_out','hot_pending','top_deal'], 'professional', 155, 'Weekly summary to Caleb via Telegram. Concise.');

-- ── ADAM TRUST SCORES (INITIAL STATE) ────────────────────────
INSERT INTO adam_trust_scores (action_type, description, category, score, threshold, autonomous, requires_caleb_approval, notes) VALUES
('send_opening_offer_a_grade', 'Send opening offer SMS to A-grade wholesaler', 'outreach', 0, 25, FALSE, TRUE, 'First to unlock. A-grade wholesalers only. After 25 clean approvals.'),
('send_opening_offer_b_grade', 'Send opening offer SMS to B-grade wholesaler', 'outreach', 0, 25, FALSE, TRUE, 'Unlocks after A-grade. B-grade relationships less established.'),
('send_opening_offer_unknown', 'Send opening offer to unknown wholesaler', 'outreach', 0, 35, FALSE, TRUE, 'Higher threshold for unknown relationships. More risk.'),
('send_follow_up_1', 'Send 4-hour follow-up to non-responsive wholesaler', 'outreach', 0, 20, FALSE, TRUE, 'Lower threshold - low-stakes action.'),
('send_follow_up_2', 'Send 24-hour final follow-up', 'outreach', 0, 20, FALSE, TRUE, 'Last contact attempt. Lower stakes.'),
('send_pof', 'Send proof of funds when requested', 'admin', 0, 10, FALSE, TRUE, 'Low risk, should unlock quickly.'),
('send_soft_no', 'Send soft no / walk away message', 'outreach', 0, 15, FALSE, TRUE, 'Relationship-preserving walk. Should unlock early.'),
('send_hard_no', 'Send firm no / deal dead message', 'outreach', 0, 20, FALSE, TRUE, 'More finality. Requires confidence Adam is reading deal correctly.'),
('mark_deal_dead', 'Mark a deal as dead in pipeline', 'admin', 0, 25, FALSE, TRUE, 'Must ensure deal is truly dead before marking. Consult Caleb first.'),
('send_counter_below_mao', 'Send counter offer below MAO', 'negotiation', 0, 30, FALSE, TRUE, 'Price commitment. Never do autonomously early in probation.'),
('send_counter_near_mao', 'Send counter offer within 5% of MAO', 'negotiation', 0, 40, FALSE, TRUE, 'High-stakes price commitment. Higher threshold.'),
('send_wholesale_blast', 'Blast deal to buyers list', 'wholesale', 0, 30, FALSE, TRUE, 'Committing to move a wholesale deal. Need confidence before autonomous.'),
('request_repair_credit', 'Request inspection repair credit from wholesaler', 'negotiation', 0, 25, FALSE, TRUE, 'Post-inspection negotiation. Requires deal context.'),
('send_buyer_followup', 'Follow up with wholesale buyer', 'wholesale', 0, 15, FALSE, TRUE, 'Lower stakes buyer follow-up.'),
('notify_grant', 'Send deal notification to Grant', 'admin', 0, 10, FALSE, TRUE, 'Internal notification. Low risk.'),
('send_deal_accepted_confirm', 'Send deal acceptance confirmation to wholesaler', 'admin', 0, 35, FALSE, TRUE, 'This confirms a contract - high stakes. Late to unlock.'),
('update_pipeline_status', 'Update deal status in Adam database', 'admin', 0, 5, FALSE, TRUE, 'Database update only. Low risk.'),
('post_group_chat_update', 'Post status update to group chat', 'reporting', 0, 5, FALSE, TRUE, 'Informational post only. Low risk.'),
('post_deal_brief', 'Post full deal brief to Caleb Telegram', 'reporting', 0, 8, FALSE, TRUE, 'Deal briefing. Low risk but should be accurate.'),
('send_relationship_checkin', 'Send periodic relationship check-in to wholesaler', 'outreach', 0, 20, FALSE, TRUE, 'Relationship maintenance. Moderate threshold.'),
('request_caleb_approval', 'Request Caleb approval on a deal or action', 'admin', 0, 3, TRUE, FALSE, 'Requesting approval is always autonomous - this is a core function.'),
('log_deal_outcome', 'Log deal outcome and lessons to brain', 'admin', 0, 3, TRUE, FALSE, 'Internal logging - always autonomous.'),
('run_brrrr_analysis', 'Run BRRRR analysis on a deal', 'analysis', 0, 3, TRUE, FALSE, 'Analysis only, no external action. Always autonomous.'),
('run_wholesale_analysis', 'Analyze deal for wholesale potential', 'analysis', 0, 3, TRUE, FALSE, 'Analysis only. Always autonomous.'),
('draft_psa', 'Draft purchase and sale agreement', 'admin', 0, 50, FALSE, TRUE, 'Legal document. Very late to unlock. Requires extensive trust.'),
('send_psa', 'Send PSA to wholesaler for signature', 'admin', 0, 60, FALSE, TRUE, 'Executing a contract. Highest threshold of all actions.');

-- ── MARKET KNOWLEDGE BASE ────────────────────────────────────
INSERT INTO market_knowledge (topic, category, subcategory, content, key_numbers, action_implications, source, confidence, applies_to_counties, applies_to_deal_types, tags) VALUES
-- LEGAL
('Florida Assignment of Contract', 'legal', 'wholesale', 'Florida allows assignment of contracts in real estate unless the original contract explicitly prohibits it. The assignor (CCG/wholesaler) assigns their contractual rights to a buyer in exchange for an assignment fee. The assignee (end buyer) steps into the original contract. A double close is the alternative when disclosure is sensitive.', 'Assignment fee: typically $5,000-30,000. No legal minimum or maximum.', 'Verify assignment clause in every wholesale deal. If "no assignment" language exists, must double close.', 'Florida Statutes', 'high', NULL, ARRAY['wholesale'], ARRAY['wholesale','legal','assignment']),
('Florida Disclosure Requirements', 'legal', 'disclosure', 'Florida Statute 689.261 requires seller to disclose known material defects that affect property value. Includes: mold, roof condition, foundation issues, prior damage, Chinese drywall, HOA issues. As investor buyer you receive disclosure. As seller after flip, you must disclose known issues.', 'Mold must be disclosed if known. Sinkholes must be disclosed per Florida statute.', 'Always document condition at purchase. Photograph everything. Proper disclosure on resale protects from future claims.', 'Florida Statutes 689.261', 'high', ARRAY['Hillsborough','Pasco','Hernando','Pinellas','Polk'], ARRAY['flip','rental','brrrr','wholesale'], ARRAY['legal','disclosure','florida']),
('Florida Sinkhole Disclosure', 'legal', 'disclosure', 'Florida law requires sellers to disclose if a property has had a sinkhole claim or if a sinkhole has been identified. Sinkhole risk varies significantly by county. Hillsborough and Pasco have moderate risk. Hernando has higher risk in some areas. Get sinkhole coverage or inspection on high-risk areas.', 'Sinkhole inspection: $400-700. Sinkhole remediation: $20,000-100,000+.', 'Always ask about prior sinkhole claims. Pull FLDFS sinkhole database. Get geological survey in high-risk areas.', 'Florida Office of Insurance Regulation', 'high', ARRAY['Hillsborough','Pasco','Hernando','Pinellas'], ARRAY['flip','rental','brrrr'], ARRAY['legal','sinkhole','florida','disclosure']),
('Open Permit Risk', 'legal', 'permits', 'Open or expired permits discovered at closing can kill a deal or create significant liability. When a permit is pulled but final inspection never called, it remains open indefinitely. Buyer inherits responsibility. Extremely common in Florida with flipped or improved properties.', NULL, 'Pull permit history on EVERY deal from county building department website before making offer. Negotiate permit resolution into contract. Open permits discovered after closing = your problem.', 'County Building Departments', 'high', NULL, ARRAY['flip','rental','brrrr','wholesale'], ARRAY['legal','permits','due_diligence']),
('HOA in Florida', 'legal', 'hoa', 'Florida HOAs have significant power including foreclosure rights for unpaid dues. Always request HOA estoppel letter showing current status, dues, pending assessments, reserves, and any violations. Rental restrictions are common - always verify if rentals are allowed before buying a rental/BRRRR. Some HOAs have lease approval requirements or minimum lease terms.', 'HOA estoppel fee: $150-500. HOA dues: highly variable $50-500+/month.', 'Always check HOA status before making offer. Ask wholesaler directly. Many HOAs restrict investor activity. CCG tries to avoid HOA properties for rentals.', 'Florida HOA Law Chapter 720', 'high', NULL, ARRAY['rental','brrrr'], ARRAY['hoa','legal','florida']),
('Florida Homestead Exemption - Investor Impact', 'legal', 'tax', 'Properties purchased by non-owner-occupants (investors) do not qualify for homestead exemption ($50,000 exemption). Save Our Homes (SOH) cap (3% annual assessment increase) is also lost when property transfers. New buyer assessed at full market value in purchase year. Significant tax increase vs prior homesteaded owner.', 'Lost homestead = $50K extra assessed value = ~$750-1,500/year additional taxes depending on county millage. SOH cap loss can be substantial on long-held properties.', 'Factor full non-homestead tax assessment into all rental and BRRRR underwriting. Use county property appraiser estimate tool for accuracy.', 'Florida Department of Revenue', 'high', NULL, ARRAY['rental','brrrr'], ARRAY['tax','homestead','florida']),
('Chinese Drywall', 'legal', 'construction', 'Defective Chinese drywall was installed primarily 2004-2008 during building boom. Emits hydrogen sulfide and other sulfur gases. Corrodes copper wiring, AC evaporator coils, electrical connections. Associated with health issues. Required disclosure by law. Remediation costs $50,000-100,000+ typically.', 'Homes most at risk: 2004-2008 construction, builder grade new construction, South Florida origin of materials.', 'For any 2004-2008 construction: smell test (rotten egg odor), check AC coils for black corrosion, check copper wiring. If suspected, get professional inspection. DO NOT BUY without major discount to account for remediation or walk away.', 'Florida Department of Health', 'high', ARRAY['Hillsborough','Pasco','Hernando','Pinellas','Polk'], ARRAY['flip','rental','brrrr'], ARRAY['construction','chinese_drywall','risk','florida']),

-- MARKET DYNAMICS
('Tampa Bay Market Overview 2024-2025', 'market_dynamics', 'overview', 'Tampa Bay remains one of the strongest real estate markets in the US. Migration from Northeast and Midwest continues. Remote work migration has largely settled but demand remains elevated. Rising insurance costs are creating affordability pressure. Condo market experiencing stress from new reserve requirements (SB 4D). Single family homes remain strong. Investor competition has increased significantly vs 2020-2021.', 'Median home price Tampa MSA: ~$400K. YoY appreciation slowing from 20%+ to 5-10%. Inventory rising but still below normal. Days on market increasing.', 'Higher prices make MAO math harder. Focus on off-market and distressed. Relationships with wholesalers are the moat. Speed still matters but not as extreme as 2021.', 'NAR, Zillow, local MLS data', 'high', ARRAY['Hillsborough','Pasco','Hernando','Pinellas','Polk'], ARRAY['flip','rental','brrrr','wholesale'], ARRAY['market','tampa','overview']),
('Florida Insurance Crisis', 'market_dynamics', 'insurance', 'Florida insurance market in significant distress. Multiple carriers have exited Florida. Citizens Insurance (state-backed insurer of last resort) has grown dramatically. Premiums have increased 30-80% in many areas in 2022-2024. Roof age is the primary factor in insurability. Homes with roofs 15+ years old face either very high premiums or difficulty getting coverage. Insurance costs materially affect investor holding costs and buyer purchasing power.', 'Average FL homeowner insurance: $4,500-8,000/year. Coastal: much higher. Roof over 15 years: add $2,000-4,000/year or uninsurable. New roof can reduce premium 15-25%.', 'Always budget realistic insurance costs. New roof pays for itself quickly in insurance savings and marketability. Coastal or flood zone = additional wind/flood coverage required.', 'Florida OIR, industry reports', 'high', ARRAY['Hillsborough','Pasco','Hernando','Pinellas','Polk'], ARRAY['flip','rental','brrrr'], ARRAY['insurance','florida','holding_costs']),
('Pasco County Growth Story', 'market_dynamics', 'county_specific', 'Pasco County is one of the fastest growing counties in Florida. Wesley Chapel, Land O Lakes, and Zephyrhills areas seeing massive new construction and population growth. Retail demand is strong. Older concrete block inventory from 1985-1995 represents the CCG sweet spot - these can be renovated to compete with new construction at significant discount. Infrastructure improvements ongoing. Good schools driving family formation.', 'Pasco population growing 3-5% annually. Wesley Chapel sub-market has seen 15%+ YoY in some zips. Older zips (33525, 33576) still 8-10%.', 'Pasco is CCG primary market for good reason. Focus deals here. Don''t overthink it. Concrete block 85-95 in good school zones are the play.', 'US Census, Pasco County Planning', 'high', ARRAY['Pasco'], ARRAY['flip','rental','brrrr','wholesale'], ARRAY['pasco','growth','market']),
('Spring Hill / Hernando Opportunity', 'market_dynamics', 'county_specific', 'Spring Hill is underappreciated by many Tampa investors. Less competition than Pasco or Hillsborough. Significant inventory of 1980-1995 concrete block. Growing as Tampa overflow market. Primary concerns: many septic systems (budget inspection), some areas have flood zone issues (check FEMA maps), slower appreciation than Pasco but better cashflow math. Strong BRRRR territory.', 'Spring Hill zips: 34606, 34607, 34608, 34609. Median prices $230K-260K. Rents: $1,650-1,750/mo 3BR.', 'Less competition = less urgent timing required. Better cash-on-cash for rental/BRRRR. Budget septic inspection on every deal. Great for patient capital.', 'Local market observation', 'high', ARRAY['Hernando'], ARRAY['rental','brrrr'], ARRAY['hernando','spring_hill','opportunity']),
('Retail vs Investor Buyers by Area', 'market_dynamics', 'buyer_profile', 'Understanding who is buying in each area drives exit strategy. Wesley Chapel, Land O Lakes, Valrico, Brandon: strong retail buyer demand - families relocating for schools and lifestyle. New Port Richey, Spring Hill, older Zephyrhills: more investor buyers, slower retail absorption. Flips in retail buyer areas exit faster and at higher prices. Rentals in investor-heavy areas have more competition for tenant quality.', 'Retail buyer areas: 30-60 DOM avg. Investor-heavy areas: 45-90 DOM avg.', 'Match exit strategy to buyer profile of the area. Dont plan a premium retail flip in an investor-dominated market.', 'MLS data analysis', 'high', ARRAY['Pasco','Hillsborough','Hernando','Pinellas'], ARRAY['flip','rental','brrrr','wholesale'], ARRAY['buyers','market','exit_strategy']),

-- CONSTRUCTION
('Concrete Block vs Frame - Florida Context', 'construction', 'materials', 'Concrete block (CBS - Concrete Block Structure) is significantly superior in Florida for both investment and resale. Better hurricane resistance. Lower insurance premiums (some carriers require CBS or offer discount). Better for Florida climate. Less susceptibility to termites. Slightly higher construction cost but dramatically better long-term. Frame homes are acceptable but CBS preferred.', 'CBS insurance discount: 5-15% depending on carrier. CBS dominates 1960-2000 Florida construction. Newer construction often hybrid.', 'Always prefer CBS. For BRRRR specifically, CBS is required by Caleb''s criteria. For flips, CBS is preferred but frame acceptable with proper due diligence.', 'Florida contractors, insurance carriers', 'high', NULL, ARRAY['flip','rental','brrrr'], ARRAY['construction','concrete_block','florida']),
('Pre-1978 Homes - Lead Paint and Asbestos', 'construction', 'hazmat', 'Homes built before 1978 may contain lead-based paint. Federal law requires disclosure to buyers and specific procedures if disturbing lead paint during renovation. Asbestos was common in floor tiles, ceiling tiles, insulation, and exterior cladding pre-1980. Testing required before disturbing asbestos. Both create cost and liability.', 'Lead paint inspection: $300-400. Asbestos testing: $400-700. Asbestos abatement: $1,000-15,000+ depending on extent.', 'Budget $1,000-2,000 testing contingency on pre-1978 homes. Disclose to end buyer even if abated. Factor abatement cost into rehab budget.', 'EPA, Florida DEP', 'high', NULL, ARRAY['flip','rental','brrrr'], ARRAY['construction','lead_paint','asbestos','pre1978']),
('1978-1999 Construction Sweet Spot', 'construction', 'era', 'This era of construction represents CCG''s ideal target range for buy/hold. CBS construction dominant. Post-1978: lead paint risk eliminated. Post-1980: asbestos largely gone. Pre-2000: homes priced significantly below new construction. Major systems (roof, HVAC, plumbing, electrical) are aged but known - quantifiable rehab. Aluminum wiring risk largely past (peak 1965-1973). Good bones, predictable issues.', 'Typical issues 1978-1999: HVAC 12-18 years (likely needs replacement), roofs 20-30 years (replacement needed), original kitchen/baths (cosmetic update), single-pane windows (upgrade).', 'This is your bread-and-butter property. Model the known capital expenditures. The predictability is the value.', 'CCG operational experience', 'high', NULL, ARRAY['flip','rental','brrrr'], ARRAY['construction','target_era','1978_1999']),
('Aluminum Wiring Risk', 'construction', 'electrical', 'Aluminum wiring was used extensively from approximately 1965-1973 due to copper shortage. Aluminum expands/contracts at different rate than devices, creating loose connections over time - fire hazard. Can be identified by silvery color at receptacle connections. Options: full rewire ($8,000-20,000), pigtailing with COPALUM connectors (proper method but expensive), or AlumiConn connectors (cheaper but requires permits).', 'Full rewire: $10,000-20,000. COPALUM pigtailing: $3,000-8,000. AlumiConn: $2,000-5,000.', 'Check any home built 1965-1973 for aluminum wiring. Most insurance companies require remediation before coverage. Factor cost into deal analysis.', 'CPSC, electrical contractors', 'high', NULL, ARRAY['flip','rental','brrrr'], ARRAY['construction','electrical','aluminum_wiring']),
('Polybutylene Plumbing', 'construction', 'plumbing', 'Polybutylene (PB) pipe was installed primarily 1978-1995 in Florida. Gray plastic pipe. Failed class action settlement in 1995. PB pipe degrades over time from chlorine in water, becomes brittle, fails catastrophically. Now essentially uninsurable or extremely expensive to insure. Full re-pipe required. Immediately disqualifying for many insurance carriers.', 'PB identification: gray plastic pipes, usually gray/silver colored fittings. Full re-pipe cost: $4,000-10,000.', 'Check any 1978-1995 home for PB. Look under sinks, in utility room. If found, deduct re-pipe cost from offer. Disclose to buyer.', 'Insurance industry, plumbing associations', 'high', NULL, ARRAY['flip','rental','brrrr'], ARRAY['construction','plumbing','polybutylene']),

-- FINANCE
('Hard Money Lending Florida', 'finance', 'lending', 'Hard money (HML) lenders provide short-term financing based on asset value rather than borrower creditworthiness. Standard terms in Tampa Bay 2024: 9-10.5% interest only, 1-3 origination points, 90% LTV on purchase, 80% LTV on ARV, 12-month term with extensions available. Draws based on rehab progress with inspection required. 3-7 business day funding typical. ENTITY REQUIRED - must close in LLC or trust.', 'CCG standard HML assumption: 9.5% interest, 2 points, 90% LTV. Monthly interest on $250K loan: ~$1,979/month.', 'Always use HML for flips unless RLOC cost is lower. RLOC at prime may be cheaper than HML - compare rates. Budget 4-5 months interest on every flip (dont use 3 month assumption - projects run long).', 'Tampa Bay HML lender landscape', 'high', NULL, ARRAY['flip','wholesale'], ARRAY['finance','hml','lending']),
('DSCR Loans for BRRRR/Rental', 'finance', 'lending', 'Debt Service Coverage Ratio (DSCR) loans qualify based on property income vs debt payment, not personal income. Ideal for investors. No tax returns required. Standard terms: 6.5-7.5% fixed rate (2024-2025), 75-80% LTV, 30-year amortization. DSCR must be 1.0-1.25x depending on lender. Rate varies with LTV, credit score, DSCR ratio.', 'CCG DSCR assumption: 6.75% rate, 75% LTV, 30-year. Monthly P&I on $180K loan: ~$1,168/month. DSCR requirement: typically 1.0x (rent >= payment).', 'Model all rentals and BRRRR at 6.75% DSCR, 75% LTV. If deal doesnt cash flow at these rates, its a pass for hold. Check current rates before committing - model conservatively.', 'Mortgage market observation', 'high', NULL, ARRAY['rental','brrrr'], ARRAY['finance','dscr','lending','brrrr']),
('CCG 20-Million RLOC Strategy', 'finance', 'ccg_specific', 'CCG has access to a $20M revolving line of credit (RLOC). This provides significant acquisition firepower. RLOC cost vs HML cost should be compared on every deal. RLOC provides speed advantage - can close in 1-3 days on right deal vs 5-7 for HML. RLOC also enables purchasing multiple simultaneous deals. Critical strategic advantage.', 'RLOC available: ~$20M. Current RLOC rate: compare to HML. HML: 9.5% + 2 points. If RLOC is cheaper, use RLOC.', 'Always know current RLOC availability and rate. If RLOC is cheaper than HML, recommend it. Speed advantage for hot deals. Monitor total deployment.', 'CCG internal', 'high', NULL, ARRAY['flip','rental','brrrr','wholesale'], ARRAY['finance','rloc','ccg','capital']),
('Closing Costs - Florida Investor Buyer', 'finance', 'closing', 'Florida closing costs for investor buyers (non-owner): title search and insurance (0.5-1% of price), doc stamps on deed ($0.70/$100 purchase price), doc stamps on mortgage ($0.35/$100 loan amount), intangible tax on mortgage (0.002 x loan amount), recording fees ($10-30/page), lender fees, attorney/title company fees. Total: typically 1-3% of purchase price.', 'Example $200K purchase: doc stamps deed = $1,400. Doc stamps mortgage = $700 (on $180K loan). Intangible tax = $360. Title insurance = $1,000-1,500. Total closing costs: ~$3,500-4,500.', 'Budget 2% of purchase price for buyer closing costs in deal underwriting. Dont forget this in all-in cost calculation.', 'Florida Statute 201.02', 'high', NULL, ARRAY['flip','rental','brrrr','wholesale'], ARRAY['finance','closing_costs','florida']),
('Selling Costs - Florida Flip', 'finance', 'closing', 'When selling a flipped property in Florida: agent commissions 5-6% (2.5-3% each side), closing costs 1-2% paid by seller, title insurance for buyer (seller typically pays in FL), doc stamps on deed ($0.70/$100), any negotiated repairs or credits. Total: typically 7-9% of sale price. CCG model uses 7.5% selling costs.', 'On $300K sale: agent commission 6% = $18K. Closing costs 1.5% = $4,500. Total out: ~$22,500 (7.5%).', 'Use 7.5% selling costs in all underwriting. Never use less than 7%. Some deals command higher commissions in new areas.', 'Florida real estate practice', 'high', NULL, ARRAY['flip','wholesale'], ARRAY['finance','selling_costs','commissions']),

-- INSURANCE
('Four-Point Inspection Requirement', 'insurance', 'requirements', 'Most Florida insurance carriers require a four-point inspection for homes 25+ years old (built before 2000 in 2025). The inspection covers: roof (age/condition), HVAC (age/type/condition), plumbing (material/condition), electrical (panel brand/condition). Results directly impact insurability and premium. Homes with poor four-point scores may be difficult to insure.', 'Four-point inspection cost: $150-250. Failing items: Federal Pacific panel, aluminum wiring, polybutylene pipe, roof 20+ years.', 'Get four-point inspection on any pre-2000 home before closing. Red flags can be negotiated into price. Know what you''re buying before you commit.', 'Florida insurance carriers', 'high', NULL, ARRAY['flip','rental','brrrr'], ARRAY['insurance','four_point','florida']),
('Wind Mitigation Inspection Value', 'insurance', 'savings', 'Wind mitigation inspections document protective features of a home to qualify for insurance discounts. Credits for: hip roof (vs gable), roof covering type, roof deck attachment, roof-to-wall connection (hurricane straps), opening protection (impact windows/shutters). Can reduce wind premium 20-40%.', 'Wind mitigation inspection: $100-200. Premium savings: $500-2,000+/year depending on features.', 'Always get wind mitigation inspection after rehab. New roof, impact windows, and hurricane straps dramatically reduce premiums. Provide inspection to listing agent for buyer marketing advantage.', 'Florida OIR', 'high', NULL, ARRAY['flip','rental','brrrr'], ARRAY['insurance','wind_mitigation','savings']),
('Flood Zone Impact on Investment', 'insurance', 'flood', 'FEMA flood zone designations significantly affect investment viability. Zone X (minimal risk): standard home insurance sufficient. Zone AE (high risk): flood insurance required by lenders. Average NFIP flood policy: $2,000-8,000/year depending on value and zone. Coastal properties may require private flood coverage. Flood zone designation affects buyer pool and resale value.', 'NFIP flood insurance: ~$1,200/year average nationally but much higher in high-risk FL. Private flood insurance: often cheaper but less predictable.', 'Check flood zone on every deal via FEMA FIRMette map before making offer. Zone AE = significant additional holding cost. Budget flood insurance in all-in analysis on any non-X zone property.', 'FEMA flood maps', 'high', ARRAY['Hillsborough','Pasco','Hernando','Pinellas'], ARRAY['flip','rental','brrrr','wholesale'], ARRAY['insurance','flood','fema','risk']),

-- TAX
('Property Tax Estimation Florida', 'tax', 'estimation', 'Florida property tax = Assessed Value x Millage Rate. As investor (non-homestead), assessed value = purchase price in first year. Millage rates by county: Hillsborough ~17-20 mills, Pasco ~18-21 mills, Hernando ~16-18 mills, Pinellas ~18-22 mills. Formula: (Purchase Price / 1000) x Millage Rate = Annual Tax.', 'Example: $250K home in Hillsborough at 19 mills = ($250,000/1,000) x 19 = $4,750/year = $396/month. Check HCPA.net for Hillsborough, PCPAO.org for Pasco, hernandopa.com for Hernando.', 'Use county property appraiser website for accurate estimates. Always budget non-homestead rate (purchase price x effective rate). Include in monthly hold cost calculation for rentals and BRRRR.', 'County property appraisers', 'high', ARRAY['Hillsborough','Pasco','Hernando','Pinellas'], ARRAY['rental','brrrr','flip'], ARRAY['tax','property_tax','estimation']),

-- DEAL STRATEGY
('The 70% Rule Explained', 'ccg_strategy', 'underwriting', 'CCG uses MAO = ARV x 70% - Repairs. This formula ensures minimum 10-15% profit margin after all costs. At 70% ARV minus repairs, assuming 7.5% selling costs, 4-5% financing, 3-4% holding costs, and the rehab itself, the net profit should be 8-12% of ARV ($25K-35K on a $300K ARV deal). This rule holds across market conditions because it bakes in the unknowns.', 'MAO example: $285K ARV, $40K repairs = ($285K x 0.70) - $40K = $199,500 - $40K = $159,500 MAO. Opening offer: $159,500 x 0.88 = $140,360.', 'Never offer above MAO. Opening offer at 88% of MAO. Hold firm above 94%. Walk above MAO unless extraordinary circumstances and Caleb personally approves.', 'Real estate investment principles', 'high', NULL, ARRAY['flip','wholesale'], ARRAY['underwriting','mao','70percent_rule']),
('BRRRR Math and Cash Left In', 'ccg_strategy', 'underwriting', 'BRRRR success metric: how much cash is left in the deal after refinance. Total cash in = purchase price + rental rehab costs. Cash returned = ARV x refi LTV (75%). Cash left in = Cash in - Cash returned. If negative: you made money AND own the property. Under 20% left in = strong BRRRR. Under 10% = excellent. Zero or negative = unicorn.', 'Example: Buy $160K + $20K rehab = $180K in. ARV $255K x 75% = $191K refi. Cash left in = $180K - $191K = -$11K (got cash OUT plus property). Unicorn deal.', 'Every BRRRR deal must be modeled to cash left in percentage. Target under 20%. Model at conservative ARV (use Urban''s number, not wholesaler''s).', 'BRRRR investment strategy', 'high', NULL, ARRAY['brrrr'], ARRAY['brrrr','underwriting','cash_left_in']),
('Wholesale Assignment vs Double Close', 'ccg_strategy', 'wholesale', 'Assignment: CCG assigns its purchase contract to end buyer. Assignment fee is paid at closing. Simple, cheap, but discloses CCG''s purchase price to end buyer. Double close: CCG actually purchases with A-to-B transaction, then immediately sells to end buyer in B-to-C transaction. More expensive (two closings, two title policies) but protects spread privacy. Some title companies wont do double closes.', 'Assignment fee: no title insurance cost. Double close: additional $2,000-4,000 in title and closing costs but spread is protected.', 'Default to assignment for deals where spread is reasonable and relationship allows. Use double close when spread is large (>$25K) and you need to protect the margin.', 'Real estate wholesale practice', 'high', NULL, ARRAY['wholesale'], ARRAY['wholesale','assignment','double_close']),
('Deal Velocity - Why Speed Matters', 'ccg_strategy', 'operations', 'In the Tampa Bay wholesale market, the best deals typically have 2-5 competing buyers. Wholesalers test buyers on response time and close capability. CCG''s competitive advantage is: (1) clarity on price, (2) response within hours not days, (3) reputation for closing what we sign, (4) Adam enabling 24/7 response. Every hour of delay on a HOT deal increases risk of losing to a competitor.', 'Target: offer sent within 30 min of deal arriving as HOT. First response to wholesaler within 15 minutes during business hours.', 'Adam''s core value prop is speed without Caleb having to be available 24/7. Probation system ensures quality. Speed kills competition.', 'Market observation', 'high', NULL, ARRAY['flip','rental','brrrr','wholesale'], ARRAY['strategy','speed','competitive_advantage']);

