INSERT INTO property_tax_data (county, millage_rate_per_1000, effective_rate_pct, assessment_ratio, homestead_exemption_amount, investor_no_homestead_notes, investor_effective_rate_pct, estimate_formula, assessor_website) VALUES
('Hillsborough', 19.2, 1.92, 100, 50000, 'Non-homestead: assessed at purchase price. No SOH cap until 2nd year. Effective rate on investment property ~1.9-2.0%.', 1.95, '(Purchase Price / 1000) * 19.2 = Annual Tax', 'https://www.hcpafl.org'),
('Pasco', 19.8, 1.98, 100, 50000, 'Pasco non-homestead slightly higher than Hillsborough. Similar structure.', 2.00, '(Purchase Price / 1000) * 19.8 = Annual Tax', 'https://www.pascopa.com'),
('Hernando', 17.5, 1.75, 100, 50000, 'Hernando lower millage than Tampa core counties. Advantage for investors holding rentals.', 1.78, '(Purchase Price / 1000) * 17.5 = Annual Tax', 'https://www.hernandopa.org'),
('Pinellas', 20.1, 2.01, 100, 50000, 'Pinellas has higher millage. Factor into rental underwriting.', 2.05, '(Purchase Price / 1000) * 20.1 = Annual Tax', 'https://pcpao.gov'),
('Polk', 16.8, 1.68, 100, 50000, 'Polk County lower taxes benefit investor math.', 1.70, '(Purchase Price / 1000) * 16.8 = Annual Tax', 'https://qpublic.schneidercorp.com/Application.aspx?AppID=838'),
('Sarasota', 18.5, 1.85, 100, 50000, 'Sarasota moderate millage but higher property values create higher absolute tax.', 1.88, '(Purchase Price / 1000) * 18.5 = Annual Tax', 'https://www.sc-pa.com');

