INSERT INTO insurance_data (county, property_type, construction_type, avg_annual_premium, min_annual_premium, max_annual_premium, wind_mitigation_discount_pct, four_point_required_year_built, market_notes, notes) VALUES
('Hillsborough', 'SFR', 'concrete_block', 3800, 2200, 8000, 22, 2000, 'Market tightening. Some carriers exiting. Citizens growing. Roofs over 15 years difficult to insure with some carriers.', 'CBS with new roof and hip design can get below $2,500/yr. Frame with old roof can exceed $7,000/yr. Shop carriers aggressively.'),
('Hillsborough', 'SFR', 'frame', 4800, 3000, 10000, 18, 2000, 'Frame homes cost more to insure than CBS in Florida. Some carriers now declining frame entirely.', 'Frame homes in flood zone can be very expensive or uninsurable.'),
('Pasco', 'SFR', 'concrete_block', 3500, 2000, 7500, 22, 2000, 'Pasco slightly less expensive than Hillsborough. Similar market trends.', 'Coastal Pasco (Hudson, Port Richey) significantly more expensive due to wind zone.'),
('Pasco', 'SFR', 'frame', 4500, 2800, 9500, 18, 2000, NULL, 'Avoid frame in coastal Pasco - insurance often exceeds budget.'),
('Hernando', 'SFR', 'concrete_block', 3200, 1800, 7000, 20, 2000, 'Hernando generally less expensive than Tampa core. Growing availability.', 'Spring Hill inland: good insurance market. Coastal Spring Hill: more expensive.'),
('Pinellas', 'SFR', 'concrete_block', 5500, 3500, 15000, 25, 2000, 'Pinellas most expensive in CCG territory due to wind exposure and flood risk. Some coastal areas very difficult to insure.', 'Inland Pinellas (Largo, Pinellas Park) more manageable. Beach areas can exceed $20K/yr.'),
('Polk', 'SFR', 'concrete_block', 2800, 1600, 6000, 18, 2000, 'Polk County less expensive - further from coast, less wind exposure.', 'Better insurance economics support better cashflow math for rentals.');

