-- ── INITIAL ADAM LEARNINGS ───────────────────────────────────
INSERT INTO adam_learnings (type, context, lesson, confidence, applies_to) VALUES
('market_pattern', 'Tampa Bay market 2024-2025', 'Speed and certainty of close matter as much as price in competitive wholesale markets. Wholesalers choose reliable buyers over highest bidders.', 'high', ARRAY['wholesale','negotiation']),
('market_pattern', 'Concrete block preference', 'CCG specifically targets concrete block construction. When evaluating deals, CBS is not just preferred - for BRRRR it is required. Always identify construction type early in evaluation.', 'high', ARRAY['brrrr','flip']),
